INSERT INTO `Faq` VALUES ('c0b8745cc933c6a471ee6','Returns','What is your return policy?','You have 14 days from delivery to return a watch in the condition received for a full refund. Returned pieces are inspected by our watchmakers; tampering or wear beyond reasonable inspection voids the policy.',6,'2026-10-11 01:00:17','2026-10-11 01:00:17'),('c3f0ae535c5f8e34935e1','Shipping','Can I collect in person?','We are an online boutique, we do not currently operate a walk-in showroom. Your watch is shipped to you insured overnight with signature required, free on every order; our concierge can arrange a video consultation before you buy.',5,'2026-10-11 01:00:17','2026-10-11 01:00:17'),('c5fe633740bc95ad11e7c','Authenticity','How is every watch authenticated?','Every timepiece passes a 40-point inspection by our master watchmakers: movement verification against serial records, dial and hand originality, case geometry, bracelet and clasp integrity, and timing tests across positions. Each watch ships with a signed Novette Watches Certificate of Authenticity.',0,'2026-10-11 01:00:17','2026-10-11 01:00:17'),('c5ff464b16b0025b27480','Shipping','Do you ship internationally?','Yes, we ship worldwide with full insurance. Import duties and taxes are the responsibility of the recipient; our concierge can estimate landed costs before you buy.',4,'2026-10-11 01:00:17','2026-10-11 01:00:17'),('c69963a2c2a825ed4314e','Shipping','How is my watch shipped?','All shipments travel in discreet, unmarked packaging with full-value insurance and signature on delivery. Orders over $5,000 ship free by insured courier; express overnight is available at $250.',3,'2026-10-11 01:00:17','2026-10-11 01:00:17'),('c8a3209b2c82ad1f1ee51','Authenticity','What does the warranty cover?','Every watch carries our two-year warranty covering the movement and its functions. Wear items such as straps, crystals damaged after delivery, and water damage from an open crown are excluded, full terms accompany your certificate.',2,'2026-10-11 01:00:17','2026-10-11 01:00:17'),('ca28697c939cbd7fe0e48','Ordering','Can I reserve a watch before purchasing?','Yes, our concierge can hold a piece for 48 hours without obligation. Reserved watches show as such on the site and are released if not confirmed.',8,'2026-10-11 01:00:17','2026-10-11 01:00:17'),('cd2234dc6f651ac7b3399','Returns','How do refunds work?','Once a return clears inspection, refunds are issued within five business days through our concierge.',7,'2026-10-11 01:00:17','2026-10-11 01:00:17'),('cf85b54d20282407451a7','Authenticity','Do your watches come with box and papers?','Where original box and papers exist we state so on the listing. Pieces without them are clearly marked and priced accordingly, authentication status never depends on paperwork.',1,'2026-10-11 01:00:17','2026-10-11 01:00:17');
/*!40000 ALTER TABLE `Faq` ENABLE KEYS */;
UNLOCK TABLES;

