INSERT INTO `Review` VALUES ('c09ac5a709d541c5ba43e',NULL,NULL,'Marcus Chen',4.5,'San Francisco, CA','Fair pricing and zero pressure. The concierge held a Tudor Black Bay while I compared options, a rare courtesy in this market.','approved','2026-09-14 00:00:00'),('c25cc0aefa2ba00918ad0',NULL,NULL,'Henrik Dahl',5.0,'Copenhagen, DK','Transparent pricing and honest grading. The heritage GMT I received had every detail disclosed in advance, there were none left to discover.','approved','2026-09-10 00:00:00'),('c31d214d1dc991ab43b64',NULL,NULL,'Tom Beckett',4.0,'Austin, TX','The item number system makes reordering painless, and every watch arrives with a condition report that reads like a lab file. Exactly what a serious buyer wants.','approved','2026-09-05 00:00:00'),('c38c6a2adee49b220aad3',NULL,NULL,'Isabella Romano',5.0,'Milan, IT','Second purchase from Novette Watches and the standard has not slipped. Their warranty service on my first watch was handled in days, not months.','approved','2026-09-15 00:00:00'),('c3f42b2eb605519e6f1c1',NULL,NULL,'Amelia Hart',4.5,'London, UK','The team sourced a Cartier Panthère for my anniversary. Authentication paperwork, service record, beautiful presentation, flawless from first call to delivery.','approved','2026-09-19 00:00:00'),('c6ef5c8fadb235361a76c',NULL,NULL,'Sofia Lindqvist',4.0,'Stockholm, SE','International shipping was fully insured and the customs paperwork was handled for me. My Grand Seiko arrived faster than a domestic order usually does.','approved','2026-09-12 00:00:00'),('c7bb6c812a0a7d94ede09',NULL,NULL,'Jonathan Meyers',5.0,'New York, NY','Purchased a Submariner through the online boutique. The condition report was exact to the last hairline, and the watch arrived insured and sized within three days.','approved','2026-09-20 00:00:00'),('ccc3d486d53578af85e90',NULL,NULL,'Priya Nair',4.0,'Toronto, CA','Bought a Lady-Datejust for my mother. The overnight delivery was complimentary, the sizing perfect, and the gift presentation far beyond what I expected.','approved','2026-09-08 00:00:00'),('ce9db0b6d13ca6c107900',NULL,NULL,'Daniel Okafor',4.0,'Chicago, IL','I was nervous buying a heritage Seamaster online. Their watchmakers talked me through every photo and the 40-point report. The watch is better than described.','approved','2026-09-18 00:00:00');
/*!40000 ALTER TABLE `Review` ENABLE KEYS */;
UNLOCK TABLES;

